const img = (code, n = 1, w = 1000, h = 1000) =>
  Array.from({ length: n }, (_, i) => {
    const path = `/catalogo/muestras/${code}-${i + 1}`
    return { path, full: `${path}-full.webp`, thumb: `${path}-thumb.webp`, w, h }
  })

